// Equations and state transitions ported from the attached Python source-model.
export const R0=900/54.29, names=['P&O','VSS-P&O','RLS-VSS','HOLD / TRACK','Full controller'];
const clip=(x,a=.1,b=.8)=>Math.max(a,Math.min(b,x));
export const defaults={G:1000,T:25,R:R0,D0:.2,N:500,noise:0,seed:0,scenario:'constant',G2:700,T2:45,R2:R0*.7,event:250,shade2:.6,shade3:.3,eta:.00008,lam:.6,step:.01,enter:.7,exit:.4,search:.15,persistence:60};
export class Plant {
 constructor(stc){this.stc=stc;this.cache=new Map()}
 params(G,T){let s=this.stc,K=T+273.15;return [G/1000*(s.Iph+.0005*(K-298.15)),s.I0*(K/298.15)**3*Math.exp(1.602176634e-19*1.12/(1.3*1.380649e-23)*(1/298.15-1/K)),s.Rs,s.Rsh,1.3*36*1.380649e-23*K/1.602176634e-19]}
 current(V,a){let [ip,i0,rs,rsh,vt]=a,I=ip;for(let n=0;n<100;n++){let e=Math.exp((V+I*rs)/vt),f=ip-i0*(e-1)-(V+I*rs)/rsh-I,df=-i0*e*rs/vt-rs/rsh-1,next=I-f/df;if(Math.abs(next-I)<1e-10)return next;I=next}throw Error('PV current solver did not converge')}
 substring(I,a){let [ip,i0,rs,rsh,vt]=a;rs/=3;rsh/=3;vt/=3;if(I>=ip*1.02)return -.7;const f=v=>ip-i0*(Math.exp((v+I*rs)/vt)-1)-(v+I*rs)/rsh-I;let lo=-5,hi=10.8;if(f(lo)*f(hi)>0)return -.7;for(let n=0;n<50;n++){let m=(lo+hi)/2;if(f(m)>0)lo=m;else hi=m}return Math.max(-.7,(lo+hi)/2)}
 point(D,G,T,R,shade=null){let rin=(1-clip(D))**2*R,V,I;if(shade){let a=shade.map(s=>this.params(G*s,T));let lo=1e-6,hi=Math.max(...shade)*G/1000*4;for(let n=0;n<50;n++){let m=(lo+hi)/2,v=Math.max(0,a.reduce((s,p)=>s+this.substring(m,p),0));if(v-m*rin>0)lo=m;else hi=m}I=(lo+hi)/2;V=Math.max(0,a.reduce((s,p)=>s+this.substring(I,p),0))}else{let a=this.params(G,T),lo=1e-6,hi=60;for(let n=0;n<45;n++){let m=(lo+hi)/2;if(this.current(m,a)-m/rin>0)lo=m;else hi=m}V=(lo+hi)/2;I=this.current(V,a)}return {V,I,P:V*I}}
 curve(G,T){let a=this.params(G,T),[ip,i0,,rsh,vt]=a,lo=0,hi=60;for(let n=0;n<100;n++){let m=(lo+hi)/2;if(ip-i0*(Math.exp(m/vt)-1)-m/rsh>0)lo=m;else hi=m}let voc=(lo+hi)/2;return Array.from({length:400},(_,k)=>{let V=k/399*voc*1.05,I=Math.max(0,this.current(V,a));return {V,I,P:V*I}})}
 mpp(G,T,R,shade){let key=JSON.stringify([G,T,R,shade]);if(this.cache.has(key))return this.cache.get(key);let p=shade?Math.max(...Array.from({length:300},(_,i)=>this.point(.1+.7*i/299,G,T,R,shade).P)):Math.max(...this.curve(G,T).map(x=>x.P));this.cache.set(key,p);return p}
}
class RLS{
 constructor(lam){this.lam=lam;this.theta=[0,0];this.p=[1000,0,0,1000];this.k=0}
 update(D,P){let [a,b,c,d]=this.p,u=a*D+b,v=c*D+d,den=this.lam+D*u+v,k0=u/den,k1=v/den,e=P-D*this.theta[0]-this.theta[1];this.theta[0]+=k0*e;this.theta[1]+=k1*e;this.p=[(a-k0*u)/this.lam,(b-k0*v)/this.lam,(c-k1*u)/this.lam,(d-k1*v)/this.lam];if(++this.k%50===0)this.p=[1000,0,0,1000];return [this.theta[0],e]}
}
function confidence(buf,r,t){buf.push([r,t]);if(buf.length>10)buf.shift();if(buf.length<2)return 0;let m=buf.reduce((s,x)=>s+x[1],0)/buf.length;return 1/(1+Math.sqrt(buf.reduce((s,x)=>s+x[0]**2,0)/buf.length)+Math.sqrt(buf.reduce((s,x)=>s+(x[1]-m)**2,0)/buf.length)/80)}
export function conditions(o,k){let G=o.G,T=o.T,R=o.R,shade=null,sigma=o.noise;if(o.scenario==='irradiance'&&k>=o.event)G=o.G2;if(o.scenario==='temperature'&&k>=o.event)T=o.T2;if(o.scenario==='load'&&k>=o.event)R=o.R2;if(o.scenario==='rapid')G=o.G*[1,.5,.8,.3,.9][Math.min(4,Math.floor(k/(o.N/5)))];if(o.scenario==='shading'&&k>=o.event||o.scenario==='trap')shade=[1,o.shade2,o.shade3];if(o.scenario==='burst')sigma=k>=150&&k<400?8:0;return {G,T,R,shade,sigma}}
export function simulate(plant,o,type,noise){let D=o.D0,prevP=null,prevD=null,dir=1,est=new RLS(o.lam),buf=[],state='TRACK',high=0,low=0,searchCount=0,ever=false,si=0,bestP=-Infinity,bestD=D,ni=0,rows=[];for(let k=0;k<o.N;k++){let c=conditions(o,k),stateUsed=state;if(state==='SEARCH')D=.1+.7*si/14;let Dused=D,p=plant.point(D,c.G,c.T,c.R,c.shade),theta=null,C=null,perturbed=true;
 if(state==='SEARCH'){if(p.P>bestP){bestP=p.P;bestD=D}if(++si>=15){D=clip(bestD);est=new RLS(o.lam);buf=[];state='TRACK'}C=0;theta=0}
 else {let measured=p.P+(c.sigma>0?noise[ni++]*c.sigma:0);if(type<2){let step=type===0?o.step:.02;if(prevP!==null){let dp=measured-prevP;if(type===1){let dd=D-prevD;step=clip(.00025*Math.abs(Math.abs(dd)>1e-9?dp/dd:0),.0008,.02)}if(measured<=prevP)dir*=-1}prevD=D;prevP=measured;D=clip(D+dir*step)}else{let [th,res]=est.update(D,measured);theta=th;C=confidence(buf,res,th);perturbed=false;if(state==='TRACK'){D=clip(D+clip(o.eta*th,-.02,.02));perturbed=true;if(type>=3){high=C>o.enter&&Math.abs(th)<5?high+1:0;if(high>=5){state='HOLD';ever=true;high=low=searchCount=0}if(type===4&&ever){searchCount=C<o.search?searchCount+1:0;if(searchCount>=o.persistence){state='SEARCH';si=0;bestP=-Infinity;searchCount=0}}}}else if(state==='HOLD'){low=C<o.exit?low+1:0;if(low>=5){state='TRACK';high=low=0}}}}
 rows.push({...p,k,D,Dused,state,stateUsed,theta_hat:theta,confidence:C,perturbed,G:c.G,T:c.T,R:c.R,shade:c.shade,pmpp:plant.mpp(c.G,c.T,c.R,c.shade)});
 }return rows}
export function metrics(rows){let n=rows.length,tail=rows.slice(-50),avg=a=>a.reduce((s,x)=>s+x,0)/a.length;return {eta:100*avg(rows.map(x=>x.P/x.pmpp)),ss:100*avg(tail.map(x=>x.P/x.pmpp)),activity:avg(rows.map(x=>Number(x.perturbed))),osc:Math.max(...tail.map(x=>x.D))-Math.min(...tail.map(x=>x.D)),sum:rows.reduce((s,x)=>s+x.P,0)}}
